// VALIDACIÓN ANTI-UNDEFINED: abortar si falta tema o blog
const input = $('Workflow Input').item.json;
if (!input.TEMA_ARTICULO || input.TEMA_ARTICULO === 'undefined' || input.TEMA_ARTICULO.trim() === '') {
  throw new Error('VALIDATION_FAILED: TEMA_ARTICULO vacío o undefined — abortando generación');
}
if (!input.ID_BLOG || input.ID_BLOG === 'undefined') {
  throw new Error('VALIDATION_FAILED: ID_BLOG vacío — falta configurar BLOGS_SITES_CONFIG');
}

// Buscar config del blog en BLOGS_SITES_CONFIG (columnas: ID_BLOG, SITIO_URL, NICHO, IDIOMA, BLOGGER_ID)
const allConfigs = $('Read NICHE_CONFIG').all().map(i => i.json);
let cfg = allConfigs.find(c => c.ID_BLOG === input.ID_BLOG) || allConfigs.find(c => c.NICHO === input.NICHO) || null;

// Config por defecto si no se encuentra el blog
if (!cfg) {
  cfg = { ID_BLOG: input.ID_BLOG, NICHO: input.NICHO || 'general', IDIOMA: input.IDIOMA || 'es',
    SITIO_URL: '', BLOGGER_ID: '', TONE: 'informativo, experto',
    AUDIENCE: 'lectores interesados en el tema', MIN_WORDS: 1200, MAX_WORDS: 1600, PROMPT_EXTRA: '' };
}

const lang = cfg.IDIOMA || input.IDIOMA || 'es';
const niche = cfg.NICHO || input.NICHO || 'general';
const es = lang === 'es';
const displayName = cfg.SITIO_URL ? cfg.SITIO_URL.replace(/https?:\/\//, '').split('/')[0] : niche;

const monetBlock = es
? `BLOQUES DE MONETIZACIÓN OBLIGATORIOS (insertar exactamente en estas posiciones):\n"
"1) Después del 2do párrafo:\n"
"<div class=\"rec-productos\"><h3>Productos recomendados</h3><ul>\n"
"<li><!-- PROD1_NAME --> - <a href=\"<!-- PROD1_URL -->\" rel=\"nofollow sponsored\" target=\"_blank\">Ver en Amazon</a></li>\n"
"<li><!-- PROD2_NAME --> - <a href=\"<!-- PROD2_URL -->\" rel=\"nofollow sponsored\" target=\"_blank\">Ver en Amazon</a></li>\n"
"<li><!-- PROD3_NAME --> - <a href=\"<!-- PROD3_URL -->\" rel=\"nofollow sponsored\" target=\"_blank\">Ver en Amazon</a></li>\n"
"</ul></div>\n"
"2) A la mitad del artículo después de un H2:\n"
"<div class=\"cta-telegram\"><p>💬 ¿Dudas? Únete gratis: <a href=\"<!-- TELEGRAM_URL -->\" target=\"_blank\"><!-- TELEGRAM_NAME --></a></p></div>\n"
"3) Al final, antes del cierre:\n"
"<div class=\"cta-final\"><p>📥 Descarga gratis: <a href=\"<!-- LEAD_MAGNET_URL -->\" target=\"_blank\"><!-- LEAD_MAGNET_NAME --></a></p></div>\n"
"`
: `MANDATORY MONETIZATION BLOCKS:\n"
"1) After 2nd paragraph:\n"
"<div class=\"rec-products\"><h3>Recommended products</h3><ul>\n"
"<li><!-- PROD1_NAME --> - <a href=\"<!-- PROD1_URL -->\" rel=\"nofollow sponsored\" target=\"_blank\">Check on Amazon</a></li>\n"
"<li><!-- PROD2_NAME --> - <a href=\"<!-- PROD2_URL -->\" rel=\"nofollow sponsored\" target=\"_blank\">Check on Amazon</a></li>\n"
"<li><!-- PROD3_NAME --> - <a href=\"<!-- PROD3_URL -->\" rel=\"nofollow sponsored\" target=\"_blank\">Check on Amazon</a></li>\n"
"</ul></div>\n"
"2) Mid-article after H2:\n"
"<div class=\"cta-telegram\"><p>💬 Questions? Join free: <a href=\"<!-- TELEGRAM_URL -->\" target=\"_blank\"><!-- TELEGRAM_NAME --></a></p></div>\n"
"3) End of article:\n"
"<div class=\"cta-final\"><p>📥 Free guide: <a href=\"<!-- LEAD_MAGNET_URL -->\" target=\"_blank\"><!-- LEAD_MAGNET_NAME --></a></p></div>\n"
"`;

const tone = cfg.TONE || 'informativo, experto';
const audience = cfg.AUDIENCE || 'lectores del tema';
const promptExtra = cfg.PROMPT_EXTRA || '';
const minWords = cfg.MIN_WORDS || 1200;
const maxWords = cfg.MAX_WORDS || 1800;

const sys = es
  ? `Eres experto SEO y escritor de contenido sobre ${niche}. Tono: ${tone}. Audiencia: ${audience}. Escribe SOLO HTML puro sin markdown, sin bloques de código, sin explicaciones.`
  : `Expert SEO writer for ${niche}. Tone: ${tone}. Audience: ${audience}. Output ONLY pure HTML, no markdown, no code blocks.`;

const usr = es
? `Escribe en español un artículo sobre: "${input.TEMA_ARTICULO}"\n"
"Keywords: ${input.KEYWORD || ''}\n"
"Extensión: ${minWords}-${maxWords} palabras\n"
"Estructura: <h1> título, introducción 2 párrafos, 4-5 <h2> con 2-3 párrafos cada uno, conclusión con CTA.\n"
"${promptExtra}\n"
"${monetBlock}\n"
"Empieza DIRECTAMENTE con <h1>, sin preámbulos.`
: `Write in English an article about: "${input.TEMA_ARTICULO}"\n"
"Keywords: ${input.KEYWORD || ''}\n"
"Length: ${minWords}-${maxWords} words\n"
"Structure: <h1> title, intro 2 paragraphs, 4-5 <h2> sections, conclusion with CTA.\n"
"${promptExtra}\n"
"${monetBlock}\n"
"Start DIRECTLY with <h1>, no preamble.`;

return { json: { ...input, bloggerId: cfg.BLOGGER_ID || '', nicheDisplay: niche, systemPrompt: sys, userPrompt: usr, language: lang } };

const res = $('DeepSeek API').item.json;
const prev = $('Build Prompt + Monetizacion').item.json;
if (!res.choices || !res.choices[0]) {
  throw new Error('DeepSeek sin choices: ' + JSON.stringify(res).substring(0, 300));
}
let html = (res.choices[0].message.content || '').trim();
if (!html || html.length < 200) throw new Error('HTML vacío o muy corto');
// Limpiar markdown fences si DeepSeek los añadió
html = html.replace(/^```html\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```\s*$/i, '').trim();
if (!html.includes('<h') || !html.includes('<p>')) throw new Error('HTML sin estructura válida: faltan h o p');
const words = html.replace(/<[^>]+>/g, ' ').split(/\s+/).filter(w => w.length > 2).length;
const tok = res.usage || {};
return { json: {
  ID_UNICO: prev.ID_UNICO,
  TEMA_ARTICULO: prev.TEMA_ARTICULO,
  ID_BLOG: prev.ID_BLOG,
  BLOGGER_ID: prev.bloggerId,
  NICHO: prev.nicheDisplay,
  IDIOMA: prev.language,
  HTML_FINAL: html,
  WORD_COUNT: words,
  TOKENS_USED: tok.total_tokens || 0,
  GENERATED_AT: new Date().toISOString(),
  HAS_MONETIZATION: html.includes('PROD1_NAME') || html.includes('cta-telegram')
}};

const prev = $('Build Prompt + Monetizacion').item.json;
const retries = parseInt(prev.RETRY_COUNT||'0');
if (retries >= 2) throw new Error('DeepSeek fallo 3 veces consecutivas');
return { json: { ...prev, RETRY_COUNT: retries + 1 } };

const d = $('Extraer y Validar HTML').item.json;
return { json: {
  HTML_FINAL: d.HTML_FINAL,
  ID_UNICO: d.ID_UNICO,
  TEMA_ARTICULO: d.TEMA_ARTICULO,
  ID_BLOG: d.ID_BLOG,
  BLOGGER_ID: d.BLOGGER_ID,
  NICHO: d.NICHO,
  IDIOMA: d.IDIOMA,
  TOKENS_USED: d.TOKENS_USED,
  WORD_COUNT: d.WORD_COUNT,
  HAS_MONETIZATION: d.HAS_MONETIZATION
}};
